import { useEffect, useState } from 'react';
import { getPosts } from '../utils/storage';
import { getAuthorName } from '../utils/auth';
import './styles/EditorDashboard.scss';

function EditorDashboard() {
  const [stats, setStats] = useState({
    total: 0,
    categories: [],
    tags: [],
    latestDate: null,
  });

  const [myPosts, setMyPosts] = useState([]);
  const [likes, setLikes] = useState({});
  const [comments, setComments] = useState({});
  const [newComments, setNewComments] = useState({});

  const author = getAuthorName();

  // Helpers
  const getLikes = (id) =>
    parseInt(localStorage.getItem(`likes-${id}`)) || 0;

  const getComments = (id) =>
    JSON.parse(localStorage.getItem(`comments-${id}`)) || [];

  const addComment = (id, name, text) => {
    const current = getComments(id);
    const updated = [...current, { name, text, time: new Date().toISOString() }];
    localStorage.setItem(`comments-${id}`, JSON.stringify(updated));
  };

  const incrementLike = (id) => {
    const count = getLikes(id) + 1;
    localStorage.setItem(`likes-${id}`, count.toString());
    return count;
  };

  useEffect(() => {
    const allPosts = Array.isArray(getPosts()) ? getPosts() : [];
    const filtered = allPosts.filter((p) => p.author === author);

    const postsWithStats = filtered.map((post) => ({
      ...post,
      views: Math.floor(Math.random() * 500),
      commentsCount: Math.floor(Math.random() * 20),
    }));

    const allTags = filtered.flatMap((p) => p.tags || []);
    const allCategories = filtered.map((p) => p.category || 'uncategorized');
    const latest = filtered
      .map((p) => p.createdAt)
      .sort()
      .reverse()[0];

    setStats({
      total: filtered.length,
      categories: [...new Set(allCategories)],
      tags: [...new Set(allTags)],
      latestDate: latest ? new Date(latest).toLocaleDateString() : 'N/A',
    });

    setMyPosts(postsWithStats);

    // Load likes/comments
    const likeMap = {};
    const commentMap = {};
    filtered.forEach((p) => {
      likeMap[p.id] = getLikes(p.id);
      commentMap[p.id] = getComments(p.id);
    });
    setLikes(likeMap);
    setComments(commentMap);
  }, [author]);

  return (
    <div className="editor-dashboard">
      <h2>Welcome, {author}</h2>

      <div className="editor-dashboard__grid">
        <div className="card">
          <h3>Total Posts</h3>
          <p>{stats.total}</p>
        </div>
        <div className="card">
          <h3>Categories</h3>
          <p>{stats.categories.join(', ') || 'None'}</p>
        </div>
        <div className="card">
          <h3>Tags Used</h3>
          <p>{stats.tags.length}</p>
        </div>
        <div className="card">
          <h3>Latest Post</h3>
          <p>{stats.latestDate}</p>
        </div>
      </div>

      <hr className="editor-dashboard__divider" />

      <h3 className="editor-dashboard__subheading">My Posts</h3>
      <div className="editor-dashboard__posts">
        {myPosts.length === 0 ? (
          <p>No posts found.</p>
        ) : (
          myPosts.map((post) => (
            <div key={post.id} className="editor-dashboard__post-card">
              <h4>{post.title}</h4>
              <p className="editor-dashboard__meta">
                Category: <strong>{post.category}</strong> • Tags:{' '}
                <em>{post.tags.join(', ') || 'None'}</em>
              </p>

              <p className="editor-dashboard__stats">
                👁 {post.views} views &nbsp; 💬 {post.commentsCount} comments
              </p>

              <button
                onClick={() => {
                  const updated = incrementLike(post.id);
                  setLikes({ ...likes, [post.id]: updated });
                }}
                className="editor-dashboard__like-btn"
              >
                ❤️ {likes[post.id] || 0}
              </button>

              <div className="editor-dashboard__comment-section">
                <form
                  onSubmit={(e) => {
                    e.preventDefault();
                    if (!newComments[post.id]) return;

                    addComment(post.id, author, newComments[post.id]);
                    const updated = getComments(post.id);
                    setComments({ ...comments, [post.id]: updated });
                    setNewComments({ ...newComments, [post.id]: '' });
                  }}
                >
                  <input
                    type="text"
                    placeholder="Write a comment..."
                    value={newComments[post.id] || ''}
                    onChange={(e) =>
                      setNewComments({
                        ...newComments,
                        [post.id]: e.target.value,
                      })
                    }
                  />
                  <button type="submit">Post</button>
                </form>

                <div className="editor-dashboard__comment-list">
                  {comments[post.id]?.map((c, i) => (
                    <div key={i} className="editor-dashboard__comment">
                      <strong>{c.name}</strong>: {c.text}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default EditorDashboard;
